Func<BoundingBoxXYZ, object> B = bb => bb==null?null:new{min=new[]{Math.Round(bb.Min.X*0.3048,2),Math.Round(bb.Min.Y*0.3048,2),Math.Round(bb.Min.Z*0.3048,2)},max=new[]{Math.Round(bb.Max.X*0.3048,2),Math.Round(bb.Max.Y*0.3048,2),Math.Round(bb.Max.Z*0.3048,2)}};
var imports = new FilteredElementCollector(doc).OfClass(typeof(ImportInstance)).Cast<ImportInstance>().Select(i=>new{id=i.Id.IntegerValue,name=(doc.GetElement(i.GetTypeId()) as ElementType)?.Name,linked=i.IsLinked,bb=B(i.get_BoundingBox(null))}).ToList();
var ds = new FilteredElementCollector(doc).OfClass(typeof(DirectShape)).Cast<DirectShape>().Select(d=>new{id=d.Id.IntegerValue,name=d.Name,cat=d.Category?.Name,bb=B(d.get_BoundingBox(null))}).Take(30).ToList();
var links = new FilteredElementCollector(doc).OfClass(typeof(RevitLinkInstance)).Cast<RevitLinkInstance>().Where(l=>l.Name.ToLower().Contains("canopy")||l.Name.ToLower().Contains("ifc")).Select(l=>new{id=l.Id.IntegerValue,l.Name}).ToList();
var fams = new FilteredElementCollector(doc).OfClass(typeof(Family)).Cast<Family>().OrderByDescending(f=>f.Id.IntegerValue).Take(12).Select(f=>new{id=f.Id.IntegerValue,f.Name,cat=f.FamilyCategory?.Name,inst=f.GetFamilySymbolIds().Sum(s=>new FilteredElementCollector(doc).OfClass(typeof(FamilyInstance)).Cast<FamilyInstance>().Count(x=>x.Symbol.Id==s))}).ToList();
var gm = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_GenericModel).WhereElementIsNotElementType().OfClass(typeof(FamilyInstance)).Cast<FamilyInstance>().OrderByDescending(f=>f.Id.IntegerValue).Take(15).Select(f=>new{id=f.Id.IntegerValue,fam=f.Symbol.Family.Name,typ=f.Symbol.Name,group=f.GroupId.IntegerValue,bb=B(f.get_BoundingBox(null))}).ToList();
return new{imports,directShapes=ds,links,recentFamilies=fams,recentGenericModels=gm};
